130	    /**
131	     * Title-case a city name: the first letter of each whitespace-separated word
132	     * is upper-cased and the remaining letters lower-cased.
133	     */
134	    private String titleCase(String city) {
135	        StringBuilder sb = new StringBuilder(city.length());
136	        boolean startOfWord = true;
137	        for (int i = 0; i < city.length(); i++) {
138	            char c = city.charAt(i);
139	            if (Character.isWhitespace(c)) {
140	                startOfWord = true;
141	                sb.append(c);
142	            } else if (startOfWord) {
143	                sb.append(Character.toUpperCase(c));
144	                startOfWord = false;
145	            } else {
146	                sb.append(Character.toLowerCase(c));
147	            }
148	        }
149	        return sb.toString();
150	    }
151	
152	    /**
153	     * Build the customer code for a newly created owner, formatted as
154	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
155	     * that already exist in that city, zero-padded to four digits.
156	     */
157	    private String buildCustomerCode(String city) {
158	        long ownersInCity = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
160	            .count();
161	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
162	    }
