16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "membership_number")
62	    private Integer membershipNumber;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    public String getAddress() {
71	        return this.address;
72	    }
73	
74	    public void setAddress(String address) {
75	        this.address = address;
76	    }
77	
78	    public String getCity() {
79	        return this.city;
80	    }
81	
82	    public void setCity(String city) {
83	        this.city = city;
84	    }
85	
86	    public String getTelephone() {
87	        return this.telephone;
88	    }
89	
90	    public void setTelephone(String telephone) {
91	        // Store telephone numbers as digits only, stripping spaces, dashes and
92	        // parentheses so that formatted input such as "(613) 555-0100" is kept
93	        // and compared as "6135550100".
94	        this.telephone = telephone == null ? null : telephone.replaceAll("[\\s()-]", "");
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    public void setEmail(String email) {
102	        this.email = email;
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public Integer getMembershipNumber() {
114	        return this.membershipNumber;
115	    }
